export function sumA(values: number[]): number {
  let total = 0;
  for (const value of values) {
    if (value > 10) {
      total += value * 2;
    } else {
      total += value;
    }
  }
  const scaled = total * 3;
  const shifted = scaled + 7;
  return shifted - 1;
}

